import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Ex10NestedQueryVsResult {

    static class Db {
        final Map<Integer, String> depts = new LinkedHashMap<Integer, String>();
        final Map<Integer, List<String>> users = new LinkedHashMap<Integer, List<String>>();
        int sqlCount = 0;
        int rowsRead = 0;

        Db() {
            for (int d = 1; d <= 5; d++) {
                depts.put(d, "D" + d);
                List<String> us = new ArrayList<String>();
                for (int u = 1; u <= 4; u++) {
                    us.add("D" + d + "-U" + u);
                }
                users.put(d, us);
            }
        }

        List<Integer> selectDeptIds() {
            sqlCount++;
            List<Integer> ids = new ArrayList<Integer>(depts.keySet());
            rowsRead += ids.size();
            return ids;
        }

        List<String> selectUsersByDept(int deptId) {
            sqlCount++;
            List<String> us = users.get(deptId);
            rowsRead += us.size();
            return us;
        }

        String[][] selectJoinRows() {
            sqlCount++;
            String[][] rows = new String[20][2];
            int k = 0;
            for (Map.Entry<Integer, String> e : depts.entrySet()) {
                for (String u : users.get(e.getKey())) {
                    rows[k][0] = e.getValue();
                    rows[k][1] = u;
                    k++;
                }
            }
            rowsRead += k;
            return rows;
        }
    }

    // 嵌套查询 <collection select=...>：1 + N 条 SQL
    static Map<String, List<String>> nestedQuery(Db db) {
        Map<String, List<String>> graph = new LinkedHashMap<String, List<String>>();
        for (Integer id : db.selectDeptIds()) {
            graph.put(db.depts.get(id), db.selectUsersByDept(id));
        }
        return graph;
    }

    // 嵌套结果（一次 join，按父 id 分组装配）
    static Map<String, List<String>> nestedResult(Db db) {
        Map<String, List<String>> graph = new LinkedHashMap<String, List<String>>();
        for (String[] row : db.selectJoinRows()) {
            List<String> us = graph.get(row[0]);
            if (us == null) {
                us = new ArrayList<String>();
                graph.put(row[0], us);
            }
            us.add(row[1]);
        }
        return graph;
    }

    static int userTotal(Map<String, List<String>> graph) {
        int n = 0;
        for (List<String> v : graph.values()) {
            n += v.size();
        }
        return n;
    }

    public static void main(String[] args) {
        Db db1 = new Db();
        Map<String, List<String>> g1 = nestedQuery(db1);
        System.out.println("nestedQuery  sql=" + db1.sqlCount + " rows=" + db1.rowsRead
                + " depts=" + g1.size() + " users=" + userTotal(g1));

        Db db2 = new Db();
        Map<String, List<String>> g2 = nestedResult(db2);
        System.out.println("nestedResult sql=" + db2.sqlCount + " rows=" + db2.rowsRead
                + " depts=" + g2.size() + " users=" + userTotal(g2));

        System.out.println("same graph   : " + g1.equals(g2));
        System.out.println("N+1 detected : " + (db1.sqlCount == g1.size() + 1));
        System.out.println("sql ratio    : " + (db1.sqlCount / db2.sqlCount) + "x");
        System.out.println("extra rows   : " + (db1.rowsRead - db2.rowsRead));
    }
}
